import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2026Q1 Ceph社区季度进展报告","description":"","frontmatter":{"title":"2026Q1 Ceph社区季度进展报告","date":"2026-03-01T00:00:00.000Z","updated":"2026-03-01T00:00:00.000Z","tags":["Ceph","社区动态","季度报告"],"categories":["季度总结"],"outline":"deep"},"headers":[],"relativePath":"quarterly/2026Q1_Ceph社区季度总结.md","filePath":"quarterly/2026Q1_Ceph社区季度总结.md","lastUpdated":1780468883000}'),i={name:"quarterly/2026Q1_Ceph社区季度总结.md"};function h(l,e,n,s,p,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<p>基于提供的 10 篇材料，以下是 2026Q1 Ceph 社区季度进展报告：</p><hr><h1 id="ceph-社区-2026q1-季度进展报告" tabindex="-1">Ceph 社区 2026Q1 季度进展报告 <a class="header-anchor" href="#ceph-社区-2026q1-季度进展报告" aria-label="Permalink to &quot;Ceph 社区 2026Q1 季度进展报告&quot;">​</a></h1><hr><h2 id="一、本季度重点议题" tabindex="-1">一、本季度重点议题 <a class="header-anchor" href="#一、本季度重点议题" aria-label="Permalink to &quot;一、本季度重点议题&quot;">​</a></h2><p>本季度社区讨论高度集中在以下几个反复出现的技术方向：</p><p><strong>1. RGW 存储效率优化</strong> bucket ID 与对象 prefix 字符串过长问题贯穿多次 RGW 重构会议，是本季度 RGW 方向最核心的持续性议题。详见 <a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-01-14.html">Ceph RGW Refactoring Meeting 2026-01-14</a>)。</p><p><strong>2. RGW Server-Side Encryption 演进</strong> GCM 加密模式支持、DUP 与加密结合的设计问题，在多次会议中被深入讨论，反映出社区对数据安全与存储效率协同优化的持续关注。详见 <a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-02-11.html">Ceph RGW Refactoring Meeting 2026-02-11</a>)。</p><p><strong>3. 大容量 HDD 场景下的运维挑战</strong> 随着 HDD 单盘容量突破 26TB 乃至 44TB，deep scrub 性能、PG 数量调优等运维问题在社区中引发广泛讨论。详见 <a href="/VideoSummary/posts/2026/Ceph_Use_+_Dev_Meetup_March_2026.html">Ceph Use + Dev Meetup March 2026</a>)。</p><p><strong>4. 测试基础设施扩展</strong> Teuthology 在 Sepia 实验室外的 OpenStack 环境中运行，是本季度测试工程方向的重要推进。详见 <a href="/VideoSummary/posts/2026/Running_Teuthology_Outside_of_the_Sepia_lab_With_Deepshikha_Singh.html">Running Teuthology Outside of the Sepia lab</a>)。</p><hr><h2 id="二、技术亮点" tabindex="-1">二、技术亮点 <a class="header-anchor" href="#二、技术亮点" aria-label="Permalink to &quot;二、技术亮点&quot;">​</a></h2><h3 id="rgw-bucket-id-缩短方案" tabindex="-1">RGW：bucket ID 缩短方案 <a class="header-anchor" href="#rgw-bucket-id-缩短方案" aria-label="Permalink to &quot;RGW：bucket ID 缩短方案&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-01-14.html">Ceph RGW Refactoring Meeting 2026-01-14</a>) 中，社区确定了使用 <strong>zone short ID</strong>（32-bit 整数，hex 后仅 8 字节）替代当前 40+ 字节 zone UUID 的方案。该方案可显著降低每个 RADOS 对象名称的长度，减少 OSD OMAP 中的元数据开销，在大规模小对象场景下收益尤为明显。同时讨论了通过 CLS 范围分配机制缩短 prefix 的方案，但因收益相对有限，决定优先推进 bucket ID 缩短。</p><h3 id="rgw-s3-vectors-api-—-vector-bucket实现" tabindex="-1">RGW：S3 Vectors API — Vector Bucket实现 <a class="header-anchor" href="#rgw-s3-vectors-api-—-vector-bucket实现" aria-label="Permalink to &quot;RGW：S3 Vectors API — Vector Bucket实现&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-01-21.html">Ceph RGW Refactoring Meeting 2026-01-21</a>) 详细介绍了 vector bucket 的架构设计：</p><ul><li>在 driver 层新增 <code>load_vector_bucket</code> / <code>list_vector_buckets</code> 接口</li><li>复用现有 <code>bucket_info</code> 对象，避免大规模代码改动</li><li>新增独立 pool 与独立 metadata sync section（<code>vector_bucket</code>）</li><li>通过继承 <code>RGWSI_Bucket_SObj</code> 实现 <code>RGWSI_VectorBucket_SObj</code>，差异通过 virtual 函数隔离</li></ul><h3 id="rgw-aes-256gcm-加密模式支持" tabindex="-1">RGW：AES-256GCM 加密模式支持 <a class="header-anchor" href="#rgw-aes-256gcm-加密模式支持" aria-label="Permalink to &quot;RGW：AES-256GCM 加密模式支持&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-02-11.html">Ceph RGW Refactoring Meeting 2026-02-11</a>) 中，Matthew 介绍了 AES-256-GCM 支持 PR。GCM 作为 size-changing cipher，需修复大量假设加密前后数据大小不变的代码路径，新增三个 head object 属性记录明文大小。GCM 的核心优势是任何数据损坏或密钥错误均可立即被检测。</p><h3 id="rgw-dup-与-server-side-encryption-结合设计" tabindex="-1">RGW：DUP 与 Server-Side Encryption 结合设计 <a class="header-anchor" href="#rgw-dup-与-server-side-encryption-结合设计" aria-label="Permalink to &quot;RGW：DUP 与 Server-Side Encryption 结合设计&quot;">​</a></h3><p>同一会议中，DDUP 与加密的结合方案取得重要进展：</p><ul><li>SSE-S3 / SSE-KMS 模式下 E tag 为明文 MD5，可作为去重判断依据</li><li>当前阶段限定为<strong>同 bucket 内</strong>加密对象去重，跨 bucket 因 per-bucket key 问题暂不支持</li><li>计划在 E tag 之外额外存储强 hash（SHA 或 BLAKE），供未来 multi-site sync 优化使用</li></ul><h3 id="rgw-object-history-索引条目泄漏问题" tabindex="-1">RGW：Object History 索引条目泄漏问题 <a class="header-anchor" href="#rgw-object-history-索引条目泄漏问题" aria-label="Permalink to &quot;RGW：Object History 索引条目泄漏问题&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-01-28.html">Ceph RGW Refactoring Meeting 2026-01-28</a>) 中，Bloomberg 团队报告了 OH 索引条目在所有版本删除后存在泄漏的问题，根因为清理流程中的竞态条件（race condition），影响 squid 及更早版本。社区正在编写 multi-site 测试用例以复现该问题。</p><h3 id="rgw-admin-cli帮助文档自动生成" tabindex="-1">RGW：Admin CLI帮助文档自动生成 <a class="header-anchor" href="#rgw-admin-cli帮助文档自动生成" aria-label="Permalink to &quot;RGW：Admin CLI帮助文档自动生成&quot;">​</a></h3><p>同次会议讨论了将命令描述集中定义于代码中、自动生成 man page 与 help 输出的方案，参考了 Ceph 配置选项的 YAML 元数据驱动做法，并将部分任务列为 GSoC 候选项目。</p><h3 id="rgw-lua-脚本包管理" tabindex="-1">RGW：Lua 脚本包管理 <a class="header-anchor" href="#rgw-lua-脚本包管理" aria-label="Permalink to &quot;RGW：Lua 脚本包管理&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Ceph_Tech_Talk_-_RGW_Lua_Scripting_Code_Walkthrough_-_Clip.html">Ceph Tech Talk - RGW Lua Scripting Code Walkthrough</a>) 介绍了 RGW Lua 脚本中基于 LuaRocks 的外部包管理机制，支持引入 <code>socket</code>、<code>json</code> 等第三方包，扩展脚本实用性。</p><h3 id="bluestore-elastic-shared-blobs-bug-告警机制讨论" tabindex="-1">BlueStore：Elastic Shared Blobs Bug 告警机制讨论 <a class="header-anchor" href="#bluestore-elastic-shared-blobs-bug-告警机制讨论" aria-label="Permalink to &quot;BlueStore：Elastic Shared Blobs Bug 告警机制讨论&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Ceph_User_+_Dev_Meetup_January_2026.html">Ceph User + Dev Meetup January 2026</a>) 中，社区围绕 bluestore elastic shared blobs 数据损坏 bug 的通知机制展开深入讨论。该 bug 在 Tentacle 版本已修复，Squid 修复已合并待发布，但代码修复无法恢复已损坏元数据。社区就是否引入 health warning 存在分歧，最终共识是需要更主动的通知渠道，具体方案待后续讨论。</p><h3 id="teuthology-openstack-环境支持" tabindex="-1">Teuthology：OpenStack 环境支持 <a class="header-anchor" href="#teuthology-openstack-环境支持" aria-label="Permalink to &quot;Teuthology：OpenStack 环境支持&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Running_Teuthology_Outside_of_the_Sepia_lab_With_Deepshikha_Singh.html">Running Teuthology Outside of the Sepia lab</a>) 介绍了在自有 OpenStack 环境中运行 Teuthology 的完整方案，支持与 Sepia 实验室相同的测试套件，Mass 模式执行已于本季度合并。当前限制为不支持 power cycle 及基于真实磁盘的 BlueStore 测试。</p><hr><h2 id="三、重要决策与里程碑" tabindex="-1">三、重要决策与里程碑 <a class="header-anchor" href="#三、重要决策与里程碑" aria-label="Permalink to &quot;三、重要决策与里程碑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事项</th><th>决策内容</th></tr></thead><tbody><tr><td>bucket ID 缩短方案</td><td>采用 zone short ID（8 字节 hex），优先于 prefix 缩短</td></tr><tr><td>加密 DDUP 范围</td><td>当前阶段限定同 bucket 内，跨 bucket 暂不支持</td></tr><tr><td>Vector Bucket 架构</td><td>复用 <code>bucket_info</code>，新增独立 pool 与 metadata sync section</td></tr><tr><td>BlueStore bug 通知</td><td>需要更主动通知机制，具体方案待邮件列表讨论</td></tr><tr><td>Teuthology Mass 模式</td><td>已合并，OpenStack 环境支持正式可用</td></tr><tr><td>RBD namespace quota</td><td>技术可行性已分析，底层依赖 RADOS namespace 机制，待后续推进</td></tr></tbody></table><p><strong>版本状态：</strong></p><ul><li>BlueStore elastic shared blobs bug：Tentacle 已修复发布，Squid 修复已合并待发布</li><li>RBD clone flatten读零 bug：已由 Nikola 完成初步调查，尚无 PR，需 code review</li></ul><hr><h2 id="四、社区动态" tabindex="-1">四、社区动态 <a class="header-anchor" href="#四、社区动态" aria-label="Permalink to &quot;四、社区动态&quot;">​</a></h2><h3 id="cephalocon-2025-温哥华峰会" tabindex="-1">Cephalocon 2025 温哥华峰会 <a class="header-anchor" href="#cephalocon-2025-温哥华峰会" aria-label="Permalink to &quot;Cephalocon 2025 温哥华峰会&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Cephalocon_2025_Highlights_Vancouver_s_Biggest_Ceph_Community_Gathering.html">Cephalocon 2025 Highlights</a>) 回顾了在加拿大温哥华举办的年度社区峰会，这是迄今规模最大的 Ceph 社区年度盛会之一。峰会围绕 OSD、MDS、RGW、RADOS 等核心组件演进路线，以及 BlueStore 性能优化、erasure coding 改进、Kubernetes 集成等议题展开深入讨论，充分体现了社区的开放文化。</p><h3 id="ceph-ambassador-program2026-年计划" tabindex="-1">Ceph Ambassador Program2026 年计划 <a class="header-anchor" href="#ceph-ambassador-program2026-年计划" aria-label="Permalink to &quot;Ceph Ambassador Program2026 年计划&quot;">​</a></h3><p><a href="/VideoSummary/posts/2026/Get_Involved_with_the_Ceph_Ambassador_Program_featuring_Anthony_Middleton_Ceph_Community_Manager.html">Get Involved with the Ceph Ambassador Program</a>) 中，社区经理 Anthony Middleton 介绍了 Ambassador Program 的四大目标：建设地区社区、放大用户声音、提升 Ceph 知名度、支持上游参与。2026 年重点推进标准化活动物料、透明资金申请流程，并积极招募新 Ambassador（不要求来自主要厂商）。</p><h3 id="google-summer-of-code" tabindex="-1">Google Summer of Code <a class="header-anchor" href="#google-summer-of-code" aria-label="Permalink to &quot;Google Summer of Code&quot;">​</a></h3><p>Ceph Foundation 已连续近 10 年参与 GSoC，2026 年再次获批参与资格。RGW Admin CLI 自动生成等任务已被列为 GSoC 候选项目，学员申请通道将于三月底开放。</p><h3 id="线下活动" tabindex="-1">线下活动 <a class="header-anchor" href="#线下活动" aria-label="Permalink to &quot;线下活动&quot;">​</a></h3><ul><li><strong>Ceph Days Raleigh</strong>：于本季度末举行</li><li><strong>Ceph Day London</strong>：CFP 已开放，活动定于 6 月 17 日，征稿截止 4 月 24 日</li></ul><h3 id="社区例会" tabindex="-1">社区例会 <a class="header-anchor" href="#社区例会" aria-label="Permalink to &quot;社区例会&quot;">​</a></h3><p>本季度 RGW Refactoring Meeting 保持每周举行，Ceph User + Dev Meetup 月度例会正常进行，社区参与度活跃。Bloomberg 团队持续贡献 bug 报告与测试用例。</p><hr><h2 id="五、下季度展望" tabindex="-1">五、下季度展望 <a class="header-anchor" href="#五、下季度展望" aria-label="Permalink to &quot;五、下季度展望&quot;">​</a></h2><p>基于本季度讨论，预计 2026Q2 将在以下方向持续推进：</p><ol><li><p><strong>RGW bucket ID 缩短落地</strong>：zone short ID 方案已达成共识，预计进入实现与测试阶段，相关 tail tag、bucket index shard 命名将同步受益。</p></li><li><p><strong>AES-256-GCM 加密 PR 合并</strong>：GCM 支持 PR 已进入审查阶段，预计本季度完成合并，为后续 DDUP 与加密结合奠定基础。</p></li><li><p><strong>DDUP 功能推进</strong>：依赖 split head 功能完成后方可完整实现，SSE-KMS 模式支持及跨 bucket 加密 DDUP 的 key pining 方案将在同 bucket DDUP 验证后评估。</p></li><li><p><strong>S3 Vectors API 完善</strong>：vector bucket 基础架构已设计完成，预计推进 vector 数据操作接口的实现与集成测试覆盖。</p></li><li><p><strong>BlueStore bug 通知机制</strong>：社区已达成需要更主动通知渠道的共识，预计在邮件列表形成具体方案（health warning 分级、cluster error log 等）。</p></li><li><p><strong>RBD namespace quota</strong>：技术可行性已明确，预计进入详细设计与实现阶段。</p></li><li><p><strong>Teuthology OpenStack 覆盖扩展</strong>：持续增加 job 数量、提升稳定性，Shaman 自建实例支持待确认。</p></li><li><p><strong>Ceph Day London</strong>：6 月 17 日举办，预计带来更多用户案例与性能优化实践分享。</p></li></ol><hr><p><em>本报告基于 2026Q1 季度 10 篇会议与视频总结材料整理，技术细节以原始材料为准。</em></p><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-01-14.html">Ceph RGW Refactoring Meeting 2026-01-14</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-01-21.html">Ceph RGW Refactoring Meeting 2026-01-21</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-01-28.html">Ceph RGW Refactoring Meeting 2026-01-28</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_RGW_Refactoring_Meeting_2026-02-11.html">Ceph RGW Refactoring Meeting 2026-02-11</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_Tech_Talk_-_RGW_Lua_Scripting_Code_Walkthrough_-_Clip.html">Ceph Tech Talk- RGW Lua Scripting Code Walkthrough - Clip</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_Use_+_Dev_Meetup_March_2026.html">Ceph Use + Dev Meetup March 2026</a>)</li><li><a href="/VideoSummary/posts/2026/Ceph_User_+_Dev_Meetup_January_2026.html">Ceph User + Dev Meetup January 2026</a>)</li><li><a href="/VideoSummary/posts/2026/Cephalocon_2025_Highlights_Vancouver_s_Biggest_Ceph_Community_Gathering.html">Cephalocon 2025 Highlights – Vancouvers Biggest Ceph Community Gathering!</a>)</li><li><a href="/VideoSummary/posts/2026/Get_Involved_with_the_Ceph_Ambassador_Program_featuring_Anthony_Middleton_Ceph_Community_Manager.html">Get Involved with the Ceph Ambassador Program featuring Anthony Middleton, Ceph Community Manager</a>)</li><li><a href="/VideoSummary/posts/2026/Running_Teuthology_Outside_of_the_Sepia_lab_With_Deepshikha_Singh.html">Running Teuthology Outside of the Sepia lab With Deepshikha Singh</a>)</li></ul>',58)])])}const _=a(i,[["render",h]]);export{u as __pageData,_ as default};
